const rows = $input.all().map(i => i.json).filter(r => r && r.refresh_token);
if (rows.length === 0) throw new Error('sync_tokens has no xbox refresh_token. Run GameDeck Xbox Auth Bootstrap. Continuing would send a blank token and look like an auth failure.');
return [{ json: { refresh_token: rows[0].refresh_token } }];

const th = $('Fetch Title History').first().json;
const titles = Array.isArray(th.titles) ? th.titles : [];
if (titles.length === 0) throw new Error('Title history returned no titles. Aborting rather than proceeding with an empty read. Keys seen: ' + Object.keys(th || {}).join(','));

const xuid = String($('XSTS Authorize').first().json.DisplayClaims.xui[0].xid);
const CHUNK = 100;
const out = [];
for (let i = 0; i < titles.length; i += CHUNK) {
  const slice = titles.slice(i, i + CHUNK);
  out.push({ json: { chunk_index: out.length, body: {
    arrangebyfield: 'xuid',
    xuids: [xuid],
    stats: slice.map(t => ({ name: 'MinutesPlayed', titleid: String(t.titleId) }))
  } } });
}
return out;

// ============================================================
// Xbox resolve and merge.
// Rules enforced here, each from a bug that already happened:
//  1. Never null a column this source does not own. Every field
//     carries the existing value forward when Xbox has nothing.
//  2. Uniform key set across upsert rows, or PostgREST silently
//     drops columns. Asserted below.
//  3. Strip trademark symbols BEFORE NFKD, which turns TM into 'TM'.
//  4. Never create a row off a failed lookup.
//  5. A corrected total is NOT a play session. Events are gated on
//     the title actually having been played in the window and are
//     dated by lastTimePlayed, never by today.
// ============================================================

// 7, matching PSN's Gate Play Events and Exophase's Compute Deltas. This sync was
// the one that implemented hard rule 10 correctly first and was left at 2, so it
// was conservative rather than wrong - but a platform stat that lands days after
// the session (a MinutesPlayed figure that only settles once the console next
// syncs) was being filed as reconciliation and dropped. One window, three syncs.
const EVENT_WINDOW_DAYS = 7;

const titles = Array.isArray($('Fetch Title History').first().json.titles) ? $('Fetch Title History').first().json.titles : [];
const rows = $('Get Existing Xbox Rows').all().map(i => i.json).filter(r => r && r.master_id);

if (!titles.length) throw new Error('Xbox returned no titles. Refusing to run: every row would look unmatched.');
if (!rows.length) throw new Error('Supabase returned no xbox rows. Refusing to run: every title would look new.');

// ---- MinutesPlayed ----
const stat = new Map();
const statErrors = [];
for (const it of $input.all()) {
  const res = it.json;
  const body = res && res.body ? res.body : res;
  if (res && res.statusCode && res.statusCode >= 400) { statErrors.push(res.statusCode + ' ' + JSON.stringify(body).slice(0, 200)); continue; }
  for (const coll of (body.statlistscollection || [])) {
    for (const s of (coll.stats || [])) {
      if (String(s.name).toLowerCase() !== 'minutesplayed') continue;
      const v = Number(s.value);
      if (!Number.isFinite(v)) continue;
      const tid = String(s.titleid || s.titleId || '');
      if (tid) stat.set(tid, Math.floor(v));
    }
  }
}
if (statErrors.length) throw new Error('userstats batch returned errors. Refusing to write from a partial read: ' + statErrors.slice(0, 3).join(' | '));

// ---- normalisation ----
const norm = (t) => String(t || '')
  .replace(/[™®©℠]/g, '')
  .normalize('NFKD')
  .toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]/g, '');

const EDITION = /\b(game preview|anniversary edition|complete edition|definitive edition|deluxe edition|ultimate edition|standard edition|game of the year|remastered|remaster|xbox series x\|s|xbox one|for windows|windows)\b/gi;
const stripEd = (t) => norm(String(t || '').replace(/\([^)]*\)/g, ' ').replace(EDITION, ' '));
const NON_GAME = /(launcher|^netflix|^youtube|^spotify|^disney\+|^hulu|^plex|blu-ray)/i;

// playtime_label must be written in the same run as playtime_minutes.
// Exophase hands the stored label straight back for xbox rows, so if this
// sync updated the minutes and left the label alone, nothing would ever
// repair it and the two would disagree forever.
// Format copied from the existing data: <60 -> '43m', whole hours -> '10h',
// otherwise '1h 43m'.
const fmtLabel = (m) => {
  if (m === null || m === undefined) return null;
  const n = Math.max(0, Math.floor(m));
  if (n < 60) return n + 'm';
  const h = Math.floor(n / 60), r = n % 60;
  return r === 0 ? h + 'h' : h + 'h ' + r + 'm';
};

// ---- index existing rows ----
const byId = new Map(), byNorm = new Map(), byStrip = new Map();
for (const r of rows) {
  if (r.xbox_title_id) byId.set(String(r.xbox_title_id), r);
  const n = norm(r.title); if (n && !byNorm.has(n)) byNorm.set(n, r);
  const s = stripEd(r.title); if (s && !byStrip.has(s)) byStrip.set(s, r);
}

const unmatched = [], excluded = [];
const groups = new Map(); // master_id -> candidate titles

// ---- pass 1: resolve every title to a row ----
for (const t of titles) {
  const tid = String(t.titleId);
  const name = String(t.name || '');
  if (NON_GAME.test(name)) { excluded.push({ title: name, title_id: tid, reason: 'non-game name pattern' }); continue; }

  const hist = t.titleHistory || {};
  const mp = stat.has(tid) ? stat.get(tid) : null;

  let row = null, signal = null;
  if (byId.has(tid)) { row = byId.get(tid); signal = 'xbox_title_id'; }
  else if (byNorm.has(norm(name))) { row = byNorm.get(norm(name)); signal = 'title_exact'; }
  else if (byStrip.has(stripEd(name))) { row = byStrip.get(stripEd(name)); signal = 'title_edition_stripped'; }

  if (!row) {
    const key = stripEd(name);
    const near = rows.filter(r => {
      const rk = stripEd(r.title);
      if (!rk || !key) return false;
      return rk.startsWith(key.slice(0, 10)) || key.startsWith(rk.slice(0, 10));
    }).slice(0, 3);
    unmatched.push({
      title: name, title_id: tid, minutes_played: mp, last_played: hist.lastTimePlayed || null,
      considered: [
        'xbox_title_id: no existing row carries ' + tid,
        'title_exact: no row normalises to "' + norm(name) + '"',
        'title_edition_stripped: no row strips to "' + key + '"'
      ],
      near_misses: near.map(r => ({ master_id: r.master_id, title: r.title, strips_to: stripEd(r.title) }))
    });
    continue;
  }

  if (!groups.has(row.master_id)) groups.set(row.master_id, { row, cands: [] });
  groups.get(row.master_id).cands.push({ t, tid, name, signal, mp, lastPlayed: hist.lastTimePlayed || null });
}

// ---- pass 2: pick a winner per row. Prefer the edition that actually
//      publishes MinutesPlayed, then the most recently played. ----
const games = [], events = [], matched = [], superseded = [], regressions = [], backfills = [];
const nowIso = $now.toISO();

for (const [masterId, g] of groups) {
  const ranked = g.cands.slice().sort((a, b) => {
    if ((a.mp !== null) !== (b.mp !== null)) return a.mp !== null ? -1 : 1;
    return new Date(b.lastPlayed || 0) - new Date(a.lastPlayed || 0);
  });
  const win = ranked[0];
  const row = g.row;

  for (const lose of ranked.slice(1)) {
    superseded.push({ title: lose.name, title_id: lose.tid, master_id: masterId,
      lost_to: win.name + ' (' + win.tid + ')',
      reason: (win.mp !== null && lose.mp === null) ? 'winner publishes MinutesPlayed, this one does not' : 'winner played more recently',
      minutes_played: lose.mp, note: 'reported only, never written and never deleted' });
  }

  const a = win.t.achievement || {};
  const leftAlone = [];
  const keep = (xv, existing, label) => {
    if (xv === null || xv === undefined || xv === 0) {
      if (existing !== null && existing !== undefined) leftAlone.push(label);
      return existing === undefined ? null : existing;
    }
    return xv;
  };

  let playtime = row.playtime_minutes === undefined ? null : row.playtime_minutes;
  if (win.mp !== null) {
    if (row.playtime_minutes != null && win.mp < row.playtime_minutes - 5) {
      regressions.push({ title: win.name, master_id: masterId, existing: row.playtime_minutes, xbox: win.mp, action: 'blocked, kept existing' });
    } else {
      playtime = win.mp;
    }
  } else if (row.playtime_minutes != null) {
    leftAlone.push('playtime_minutes (Xbox publishes no MinutesPlayed for this title)');
  }

  const earned  = keep(a.currentAchievements, row.earned_awards, 'earned_awards');
  const total   = keep(a.totalAchievements, row.total_awards, 'total_awards');
  const points  = keep(a.currentGamerscore, row.earned_points, 'earned_points');
  const percent = keep(a.progressPercentage, row.percent, 'percent');

  games.push({
    // environment and title are NOT NULL. PostgREST forms the INSERT tuple
    // before resolving the conflict, so they must be present even on a pure
    // update. title is the EXISTING title on purpose: Xbox names carry
    // trademark symbols and edition suffixes the library already cleaned off.
    master_id: masterId,
    environment: 'xbox',
    title: row.title,
    xbox_title_id: Number(win.tid),
    playtime_minutes: playtime,
    playtime_label: playtime === null || playtime === undefined ? (row.playtime_label === undefined ? null : row.playtime_label) : fmtLabel(playtime),
    last_played: win.lastPlayed || row.last_played || null,
    earned_awards: earned,
    total_awards: total,
    earned_points: points,
    percent: percent,
    direct_synced_at: nowIso,
    updated_at: nowIso
  });

  const dMin = (win.mp !== null && row.playtime_minutes != null && win.mp > row.playtime_minutes) ? win.mp - row.playtime_minutes : 0;
  const dAch = (earned != null && row.earned_awards != null && earned > row.earned_awards) ? earned - row.earned_awards : 0;

  // A corrected total is not a session. Only log activity if this title
  // was actually played inside the window, and date it by when it was played.
  const lp = win.lastPlayed ? DateTime.fromISO(win.lastPlayed) : null;
  const daysSince = lp ? $now.diff(lp, 'days').days : null;
  const inWindow = daysSince !== null && daysSince <= EVENT_WINDOW_DAYS;

  if (dMin > 0 || dAch > 0) {
    if (inWindow) {
      events.push({
        master_id: masterId, title: row.title, environment: 'xbox', event_date: lp.toISODate(),
        minutes_delta: dMin, achievements_delta: dAch, percent_after: percent,
        playtime_minutes_after: playtime, earned_awards_after: earned,
        last_played: win.lastPlayed, is_new: false
      });
    } else {
      backfills.push({ title: win.name, master_id: masterId, minutes_delta: dMin, ach_delta: dAch,
        days_since_played: daysSince === null ? null : Math.round(daysSince),
        note: 'total corrected on the row, no activity event: this is reconciliation, not a session' });
    }
  }

  matched.push({ title: win.name, master_id: masterId, our_title: row.title, signal: win.signal, title_id: win.tid,
    playtime_change: (row.playtime_minutes === null ? 'null' : row.playtime_minutes) + ' -> ' + playtime,
    minutes_delta: dMin, ach_delta: dAch, logged_event: (dMin > 0 || dAch > 0) && inWindow, fields_left_alone: leftAlone });
}

const keySets = new Set(games.map(g => Object.keys(g).sort().join(',')));
if (keySets.size > 1) throw new Error('Upsert payload has ' + keySets.size + ' different key sets. PostgREST would silently drop columns. Sets: ' + [...keySets].join(' || '));

return [{ json: {
  _mode: 'LIVE - Upsert Games and Insert Play Events are enabled.',
  summary: {
    xbox_titles: titles.length,
    our_xbox_rows: rows.length,
    matched: matched.length,
    unmatched_reported_not_created: unmatched.length,
    superseded: superseded.length,
    excluded_non_game: excluded.length,
    rows_to_upsert: games.length,
    events_to_insert: events.length,
    backfills_no_event: backfills.length,
    matched_by_signal: matched.reduce((m, x) => { m[x.signal] = (m[x.signal] || 0) + 1; return m; }, {}),
    playtime_regressions_blocked: regressions.length,
    upsert_key_set: [...keySets][0] || null
  },
  regressions,
  events,
  backfills_biggest: backfills.slice().sort((a, b) => b.minutes_delta - a.minutes_delta).slice(0, 15),
  fields_left_alone_sample: matched.filter(m => m.fields_left_alone.length).slice(0, 15),
  unmatched,
  superseded,
  excluded,
  games
} }];

// Which day does a play session belong to?
//
// Resolve and Merge dates each event with DateTime.toISODate(), which resolves in
// whatever zone the runtime is configured for. This instance runs on UTC, so a
// session at 10:18pm Eastern on the 12th was filed as the 13th. The app renders
// event_date as a plain calendar day in the reader's zone, so those sessions showed
// up under the wrong heading. Setting the workflow timezone did not demonstrably
// change the runtime, and an unverified setting is not a fix.
//
// So the zone is pinned here, in code, where it is visible and testable. The day a
// session belongs to is a product decision about the reader, not an infrastructure
// detail that should drift when someone changes an instance default.
const ACTIVITY_ZONE = 'America/New_York';

const src = $('Resolve and Merge').first().json;
const events = Array.isArray(src.events) ? src.events : [];

const dated = [];
const unchanged = [];
for (const e of events) {
  const lp = e.last_played ? DateTime.fromISO(e.last_played).setZone(ACTIVITY_ZONE) : null;
  if (!lp || !lp.isValid) {
    // No usable timestamp: leave whatever Resolve and Merge decided rather than
    // inventing a day. It already refuses to emit an event without one.
    unchanged.push({ title: e.title, event_date: e.event_date, reason: 'no usable last_played' });
    dated.push(e);
    continue;
  }
  const day = lp.toISODate();
  if (day !== e.event_date) {
    unchanged.push({ title: e.title, from: e.event_date, to: day, last_played: e.last_played, moved: true });
  }
  dated.push({ ...e, event_date: day });
}

return [{ json: {
  activity_zone: ACTIVITY_ZONE,
  events: dated,
  count: dated.length,
  redated: unchanged.filter(u => u.moved).length,
  notes: unchanged
} }];

const src = $('Resolve and Merge').first().json || {};
const unmatched = Array.isArray(src.unmatched) ? src.unmatched : [];
const WINDOW_DAYS = 7;
const APP = /(launcher|^netflix\b|^youtube\b|^spotify\b|^disney\+\b|^hulu\b|^plex\b|blu-ray|media player|xbox accessories|microsoft edge)/i;
const TEST_BUILD = /\b(?:demo|trial|playtest|open beta|closed beta|beta test|public test branch|test branch|test server|technical test|network test)\b/i;
const out = [];
for (const u of unmatched) {
  const title = String(u.title || '').trim();
  const tid = String(u.title_id || '').trim();
  const mp = Number(u.minutes_played);
  const lp = u.last_played ? DateTime.fromISO(u.last_played) : null;
  const days = lp && lp.isValid ? $now.diff(lp, 'days').days : null;
  if (!title || !tid) continue;
  if (APP.test(title) || TEST_BUILD.test(title)) continue;
  if (!Number.isFinite(mp) || mp <= 0) continue;
  if (days === null || days < -1 || days > WINDOW_DAYS) continue;
  out.push({ json: {
    title,
    title_id: tid,
    minutes_played: Math.floor(mp),
    last_played: u.last_played || null,
  } });
}
return out;

const WINDOW_DAYS = 7;
const ACTIVITY_ZONE = 'America/New_York';
const XBOX_BAND = 3000000000000;
const BAD_GAME_TYPES = new Set([1, 3, 5, 6, 7, 13, 14]);
const APP = /(launcher|^netflix\b|^youtube\b|^spotify\b|^disney\+\b|^hulu\b|^plex\b|blu-ray|media player|xbox accessories|microsoft edge)/i;
const TEST_BUILD = /\b(?:demo|trial|playtest|open beta|closed beta|beta test|public test branch|test branch|test server|technical test|network test)\b/i;
const EDITION = /\b(?:the complete edition|complete edition|anniversary edition|definitive edition|deluxe edition|ultimate edition|standard edition|game of the year|goty|remastered|remaster|xbox series x\|s|xbox one|for windows|windows|game preview)\b/gi;

const norm = (t) => String(t || '')
  .replace(/[™®©℠]/g, '')
  .normalize('NFKD')
  .toLowerCase()
  .replace(/&/g, 'and')
  .replace(/[^a-z0-9]/g, '');
const stripEd = (t) => norm(String(t || '').replace(/\([^)]*\)/g, ' ').replace(EDITION, ' '));
const cleanTitle = (t) => String(t || '').replace(/[™®©℠]/g, '').replace(/\s+/g, ' ').trim();
const fmtLabel = (m) => {
  const n = Math.max(0, Math.floor(Number(m) || 0));
  if (n < 60) return n + 'm';
  const h = Math.floor(n / 60), r = n % 60;
  return r === 0 ? h + 'h' : h + 'h ' + r + 'm';
};
const xboxPlatform = (g) => Array.isArray(g && g.platforms) && g.platforms.some((p) => /xbox|x360|xone|xsx|series x|series s/i.test(String(p || '')));
const positiveOrStored = (value, stored, fallback = 0) => {
  const n = Number(value);
  if (Number.isFinite(n) && n > 0) return n;
  return stored !== null && stored !== undefined ? stored : fallback;
};

const queries = $('Build Unmatched Discovery Queries').all().map((i) => i.json);
const responses = $input.all();
if (responses.length !== queries.length) {
  throw new Error('IGDB discovery responses (' + responses.length + ') do not align with queries (' + queries.length + '). Refusing to write.');
}

const source = $('Resolve and Merge').first().json || {};
const allUnmatched = Array.isArray(source.unmatched) ? source.unmatched : [];
const existing = $('Get Existing Xbox Rows').all().map((i) => i.json).filter((r) => r && r.master_id != null);
const xboxTitles = Array.isArray($('Fetch Title History').first().json.titles) ? $('Fetch Title History').first().json.titles : [];
const rawById = new Map(xboxTitles.map((t) => [String(t.titleId), t]));

const byIgdb = new Map();
for (const r of existing) {
  const id = Number(r.igdb_id);
  if (!Number.isFinite(id) || id <= 0) continue;
  if (!byIgdb.has(id)) byIgdb.set(id, []);
  byIgdb.get(id).push(r);
}

const games = [];
const events = [];
const resolved = [];
const unresolved = [];
const regressions = [];
const handledIds = new Set();
const nowIso = $now.toISO();

for (let i = 0; i < queries.length; i++) {
  const q = queries[i] || {};
  const tid = String(q.title_id || '');
  const title = String(q.title || '');
  const body = responses[i] && responses[i].json ? responses[i].json : {};
  const candidates = Array.isArray(body.games) ? body.games : [];
  const scored = [];

  for (const g of candidates) {
    if (!g || !g.id || !g.name || !g.cover) continue;
    if (g.gameType != null && BAD_GAME_TYPES.has(Number(g.gameType))) continue;
    if (!xboxPlatform(g)) continue;
    const exact = norm(g.name) === norm(title);
    const stripped = stripEd(g.name) && stripEd(g.name) === stripEd(title);
    const score = exact ? 100 : stripped ? 90 : 0;
    if (score > 0) scored.push({ g, score });
  }

  scored.sort((a, b) => b.score - a.score || Number(b.g.ratingCount || 0) - Number(a.g.ratingCount || 0));
  const best = scored[0] || null;
  if (!best) {
    unresolved.push({ title, title_id: tid, reason: 'no high-confidence Xbox IGDB match', candidates: candidates.slice(0, 5).map((g) => ({ id: g.id, name: g.name, platforms: g.platforms, gameType: g.gameType, versionParent: g.versionParent })) });
    continue;
  }

  const canonicalIgdbId = Number(best.g.versionParent || best.g.id);
  const tiedCanonical = [...new Set(scored.filter((x) => x.score === best.score).map((x) => Number(x.g.versionParent || x.g.id)))];
  if (tiedCanonical.length > 1) {
    unresolved.push({ title, title_id: tid, reason: 'ambiguous IGDB match', candidates: scored.filter((x) => x.score === best.score).map((x) => ({ id: x.g.id, name: x.g.name, canonical_igdb_id: Number(x.g.versionParent || x.g.id) })) });
    continue;
  }

  const existingHits = [];
  for (const id of [...new Set([canonicalIgdbId, Number(best.g.id)])]) {
    for (const r of (byIgdb.get(id) || [])) {
      if (!existingHits.some((x) => Number(x.master_id) === Number(r.master_id))) existingHits.push(r);
    }
  }
  if (existingHits.length > 1) {
    unresolved.push({ title, title_id: tid, reason: 'multiple existing Xbox rows share the resolved IGDB identity', master_ids: existingHits.map((r) => r.master_id) });
    continue;
  }

  const row = existingHits[0] || null;
  if (row && row.xbox_title_id != null && String(row.xbox_title_id) !== tid) {
    unresolved.push({ title, title_id: tid, reason: 'resolved row already belongs to a different xbox_title_id', master_id: row.master_id, existing_xbox_title_id: row.xbox_title_id });
    continue;
  }

  const raw = rawById.get(tid) || {};
  const ach = raw.achievement || {};
  const before = row && row.playtime_minutes != null ? Number(row.playtime_minutes) : null;
  const mp = Number(q.minutes_played);
  let playtime = Number.isFinite(mp) ? Math.max(0, Math.floor(mp)) : (before ?? 0);
  let regressed = false;
  if (before != null && Number.isFinite(mp) && mp < before - 5) {
    playtime = before;
    regressed = true;
    regressions.push({ title, title_id: tid, master_id: row.master_id, existing: before, xbox: mp, action: 'blocked, kept existing' });
  }

  const earned = positiveOrStored(ach.currentAchievements, row && row.earned_awards, 0);
  const total = positiveOrStored(ach.totalAchievements, row && row.total_awards, 0);
  const points = positiveOrStored(ach.currentGamerscore, row && row.earned_points, 0);
  const percent = positiveOrStored(ach.progressPercentage, row && row.percent, 0);
  const lastPlayed = q.last_played || (row && row.last_played) || null;
  const isNew = !row;
  const masterId = row ? Number(row.master_id) : XBOX_BAND + Number(tid);
  const gameTitle = row ? row.title : cleanTitle(best.g.name || title);
  const igdbId = row && row.igdb_id != null ? Number(row.igdb_id) : canonicalIgdbId;

  games.push({
    master_id: masterId,
    environment: 'xbox',
    title: gameTitle,
    xbox_title_id: Number(tid),
    igdb_id: igdbId,
    playtime_minutes: playtime,
    playtime_label: fmtLabel(playtime),
    last_played: lastPlayed,
    earned_awards: earned,
    total_awards: total,
    earned_points: points,
    percent,
    direct_synced_at: nowIso,
    updated_at: nowIso,
  });

  const lp = lastPlayed ? DateTime.fromISO(lastPlayed).setZone(ACTIVITY_ZONE) : null;
  const days = lp && lp.isValid ? $now.diff(lp, 'days').days : null;
  const recent = days !== null && days >= -1 && days <= WINDOW_DAYS;
  let dMin = 0;
  let dAch = 0;
  if (isNew) {
    if (recent && playtime > 0) {
      dMin = playtime;
      dAch = Number(earned) || 0;
    }
  } else if (!regressed) {
    if (before != null && playtime > before) dMin = playtime - before;
    const prevEarned = Number(row.earned_awards) || 0;
    if (Number(earned) > prevEarned) dAch = Number(earned) - prevEarned;
  }

  if ((dMin > 0 || dAch > 0) && recent) {
    events.push({
      master_id: masterId,
      title: gameTitle,
      environment: 'xbox',
      event_date: lp.toISODate(),
      minutes_delta: dMin,
      achievements_delta: dAch,
      percent_after: percent,
      playtime_minutes_after: playtime,
      earned_awards_after: earned,
      last_played: lastPlayed,
      is_new: isNew,
    });
  }

  handledIds.add(tid);
  resolved.push({
    title,
    title_id: tid,
    master_id: masterId,
    canonical_title: gameTitle,
    igdb_id: igdbId,
    igdb_match: best.g.name,
    matched_existing: Boolean(row),
    minutes_before: before,
    minutes_after: playtime,
    event_date: ((dMin > 0 || dAch > 0) && recent) ? lp.toISODate() : null,
    minutes_delta: dMin,
    achievements_delta: dAch,
  });
}

let excludedCount = 0;
let deferredCount = 0;
for (const u of allUnmatched) {
  const tid = String(u.title_id || '');
  if (handledIds.has(tid) || unresolved.some((x) => String(x.title_id) === tid)) continue;
  const title = String(u.title || '');
  const mp = Number(u.minutes_played);
  const lp = u.last_played ? DateTime.fromISO(u.last_played) : null;
  const days = lp && lp.isValid ? $now.diff(lp, 'days').days : null;
  let reason = 'outside current activity resolution window';
  if (APP.test(title)) { reason = 'non-game/app name pattern'; excludedCount++; }
  else if (TEST_BUILD.test(title)) { reason = 'demo/beta/test build'; excludedCount++; }
  else if (!Number.isFinite(mp) || mp <= 0) { reason = 'no positive Xbox playtime to baseline'; deferredCount++; }
  else if (days === null || days < -1 || days > WINDOW_DAYS) { reason = 'last_played outside ' + WINDOW_DAYS + '-day activity window'; deferredCount++; }
  else { reason = 'not selected for discovery'; deferredCount++; }
  unresolved.push({ title, title_id: tid, minutes_played: u.minutes_played, last_played: u.last_played, reason });
}

const gameKeySets = new Set(games.map((g) => Object.keys(g).sort().join(',')));
const eventKeySets = new Set(events.map((e) => Object.keys(e).sort().join(',')));
if (gameKeySets.size > 1) throw new Error('Resolved Xbox game upsert payload has inconsistent key sets.');
if (eventKeySets.size > 1) throw new Error('Resolved Xbox event payload has inconsistent key sets.');

return [{ json: {
  summary: {
    unmatched_input: allUnmatched.length,
    candidates_queried: queries.length,
    resolved: resolved.length,
    new_rows: resolved.filter((r) => !r.matched_existing).length,
    matched_existing_rows: resolved.filter((r) => r.matched_existing).length,
    events_to_insert: events.length,
    remaining_unresolved_after_run: Math.max(0, allUnmatched.length - resolved.length),
    excluded_non_game_or_test: excludedCount,
    deferred_outside_activity_window_or_no_playtime: deferredCount,
    regressions_blocked: regressions.length,
    activity_zone: ACTIVITY_ZONE,
    window_days: WINDOW_DAYS,
  },
  resolved,
  unresolved,
  regressions,
  games,
  events,
} }];
